import sys
MOD = 10**9 + 7

def prime_factors(x):
    factors = set()
    i = 2
    while i * i <= x:
        if x % i == 0:
            factors.add(i)
            while x % i == 0:
                x //= i
        i += 1
    if x > 1:
        factors.add(x)
    return factors

def main():
    x, n = map(int, sys.stdin.readline().split())
    primes = prime_factors(x)
    result = 1
    for p in primes:
        total = 0
        current = p
        while current <= n:
            total += n // current
            current *= p
        result = result * pow(p, total, MOD) % MOD
    print(result)

if __name__ == "__main__":
    main()
